changes.before:
if loading:
  show("불러오는 중")
elif error:
  show("불러오지 못했습니다")
elif items.length == 0:
  show("표시할 카드가 없습니다")
else:
  render(items)

changes.after:
if loading:
  show("Loading")
elif error:
  show("Could not load")
elif items.length == 0:
  show("No cards to show")
else:
  render(items)

if (filteredCards.length === 0) {
  showEmpty('No cards match the current filters')
}

if (currentVersion !== latestVersion) {
  showWarning('This version is outdated')
}
